import { execution } from '@dynatrace-sdk/automation-utils';
import { monitoredEntitiesClient } from '@dynatrace-sdk/client-classic-environment-v2';
import OpenAI from 'openai';

export default async function ({ execution_id }) {
  const ex = await execution(execution_id);

  // Parse event and result from the execution
  const event = ex.event();
  const result = await ex.result("execute_dql_query_1");

  // Collect affected entity IDs
  const entityIds = event['affected_entity_ids'] || [];

  // Resolve entity display names
  const names: string[] = [];
  for (const id of entityIds) {
    try {
      const detail = await monitoredEntitiesClient.getEntity({ entityId: id });
      names.push(detail.displayName || id);
    } catch {
      names.push(id); // fallback to ID if lookup fails
    }
  }

  // Extract raw timestamp from result
  const rawTimestamp = result.records?.[0]?.["timestamp"];

  // Convert to IST if present
  const istTimestamp = rawTimestamp
    ? new Date(rawTimestamp).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' })
    : 'N/A';

  // Build Markdown-friendly description
  const description = [
    `## Problem`,
    `**Name:** ${event['event.name'] || 'N/A'}`,
    `**Kind:** ${event['event.kind'] || 'N/A'}  |  **Category:** ${event['event.category'] || 'N/A'}  |  **Status:** ${event['event.status'] || 'N/A'}`,
    `**Problem ID:** ${event['display_id'] || event['event.id'] || 'N/A'}`,
    `**Maintenance Mode:** ${event['maintenance.is_under_maintenance'] !== undefined ? event['maintenance.is_under_maintenance'] : 'N/A'}`,
    `**Timestamp (IST):** ${istTimestamp}`,
    ``,
    `## Entities`,
    `- **Affected entity types:** ${(event['affected_entity_types'] || []).join(', ') || 'N/A'}`,
    `- **Affected entity names:** ${names.join(', ') || 'N/A'}`,
    `- **Root cause:** ${event['root_cause_entity_name'] || 'N/A'} (${event['root_cause_entity_id'] || ''})`,
    ``,
    `## Host & Infrastructure`,
    `- **Host name(s):** ${(event['host.name'] || []).join(', ') || 'N/A'}`,
    `- **Host group name(s):** ${(event['dt.host_group.id'] || []).join(', ') || 'N/A'}`,
    ``,
    `## Tags`,
    `- **Entity tags:** ${(event['entity_tags'] || []).join(', ') || 'N/A'}`,
    ``
  ].join('\n');

 const copilotResponse = await fetch(
  'https://wku19290.apps.dynatrace.com/platform/davis/copilot/v1/skills/conversations:message',
  {
    method: 'POST',
    headers: {
      'accept': 'application/json',
      'Content-Type': 'application/json',
      'Authorization': `Bearer <API Token>` // Replace with your actual token
    },
    body: JSON.stringify({
      text: `
You are an expert Dynatrace and observability engineer.
Given the following raw event JSON, write a clear, concise, and professional explanation of the problem for a non-technical stakeholder.
Highlight what happened, which systems are impacted, and any relevant context. Based on the problem also see if similar problems occured for the affected entity in last 7 days and mention the reference to the problems as well like count and other important details. 

${description}
      `.trim()
    })
  }
);

const copilotData = await copilotResponse.json();
const aiExplanation = copilotData.text || 'No explanation generated.';


  return {
    description,        // Markdown-formatted technical details
    entityNames: names, // Resolved entity names
    aiExplanation       // Human-friendly summary from OpenAI
  };
}
